import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { AgentRun, AskContext, CommandRunner, Harness, HarnessReply } from "@amykit/core";
import { costOf, specFor } from "@amykit/model-specs";
import { ParsedRun, parseRun } from "./envelope.js";

export interface ClaudeHarnessConfig {
  /** Passed to the CLI as --model. Omit to use whatever the CLI defaults to. */
  model?: string;
  timeoutMs?: number;
}

/**
 * What keeps a run apart from the operator's own Claude.
 *
 * Without these a ticket run read the operator's personal CLAUDE.md, every
 * skill they had installed, their hooks and plugins, and kept a session and
 * an auto-memory under `~/.claude/projects`. The repository's own settings —
 * `project` and `local` — still load: they belong to the code being worked
 * on, not to the person running amy.
 */
export const ISOLATED = [
  "--setting-sources",
  "project,local",
  "--strict-mcp-config",
  "--no-session-persistence",
] as const;

/**
 * Lends one skill to a run: a fresh directory whose `.claude/skills/<name>`
 * links to where the skill is installed, for `--add-dir`.
 *
 * Dropping the user setting source drops `~/.claude/skills` with it, so the
 * skill a step was addressed to is handed over by place, and nothing else of
 * the operator's comes along. A skill whose directory is gone is not lent,
 * and the run goes ahead without it.
 */
export function lend(tmpDir: string, skill: { name: string; path: string }): string | undefined {
  // Absolute, since a link is read from where it lies: a relative skill root
  // would otherwise point inside the lent directory and lend nothing.
  const source = path.resolve(skill.path);
  if (!fs.existsSync(path.join(source, "SKILL.md"))) return undefined;

  const root = fs.mkdtempSync(path.join(tmpDir, "amy-claude-skill-"));
  const skills = path.join(root, ".claude", "skills");
  fs.mkdirSync(skills, { recursive: true });
  fs.symlinkSync(source, path.join(skills, skill.name), "dir");
  return root;
}

/**
 * The `claude` CLI, and everything knowable about what a call to it took.
 *
 * `--output-format json` is what makes the run measurable rather than
 * guessed: it returns the answer, the token counts, the cost the harness
 * itself worked out, and an error status to classify on.
 */
export class ClaudeHarness implements Harness {
  readonly name = "claude";

  constructor(
    private readonly runner: CommandRunner,
    private readonly config: ClaudeHarnessConfig = {},
    private readonly tmpDir: string = os.tmpdir(),
  ) {}

  async ask(prompt: string, cwd: string, context: AskContext = {}): Promise<HarnessReply> {
    const asked = this.config.model ?? "";
    const args: string[] = [];
    if (this.config.model) {
      args.push("--model", this.config.model);
    }
    // Plan mode reads and does not edit or run anything, enforced by the CLI.
    if (context.readOnly) args.push("--permission-mode", "plan");
    args.push(...ISOLATED);

    const lent = context.skill ? lend(this.tmpDir, context.skill) : undefined;
    if (lent) args.push("--add-dir", lent);
    args.push("--output-format", "json", "-p");

    const started = Date.now();
    let result: Awaited<ReturnType<CommandRunner["run"]>>;
    try {
      result = await this.runner.run("claude", args, {
        cwd,
        stdin: prompt,
        timeoutMs: this.config.timeoutMs,
      });
    } finally {
      if (lent) fs.rmSync(lent, { recursive: true, force: true });
    }
    const elapsed = Date.now() - started;

    const parsed = parseRun(result.stdout, result.ok, asked);
    return { text: parsed.text, run: this.account(parsed, elapsed, result.stderr) };
  }

  /**
   * Turns a parsed run into the account the engine logs and the budget spends.
   *
   * A cost the harness reported wins, because it knows the plan and the
   * discounts. Failing that, the vendored table computes one and says so. A
   * model the table has never heard of leaves the cost absent rather than
   * inventing a rate to spend against a ceiling.
   */
  private account(parsed: ParsedRun, elapsedMs: number, stderr: string): AgentRun {
    let costUsd = parsed.costUsd;
    let costSource = parsed.costSource;

    if (costUsd === undefined && parsed.tokens) {
      const spec = specFor(parsed.model);
      if (spec) {
        costUsd = costOf(spec, parsed.tokens);
        costSource = "computed";
      }
    }

    return {
      outcome: parsed.outcome,
      harness: this.name,
      model: parsed.model,
      tokens: parsed.tokens,
      costUsd,
      costSource,
      durationMs: parsed.durationMs ?? elapsedMs,
      output: [parsed.text, stderr].filter(Boolean).join("\n").trim(),
    };
  }
}

import { ConfigSchema } from "@amykit/core";

/** What this plugin needs told to it, and nothing more. */
export const configSchema = {
  model: {
    type: "string",
    description: "passed to the CLI as --model, which is the flag it accepts",
    default: "",
  },
  models: {
    type: "string[]",
    description:
      "the model tiers to offer the relay, cheapest first. One agent is contributed per tier, named `claude:<model>`. Empty means a single agent using `model`",
    default: [],
  },
  timeoutMs: {
    type: "number",
    description: "how long one agent call may run before it is given up on",
    default: 30 * 60 * 1000,
  },
} satisfies ConfigSchema;

import { AgentOutcome, CostSource, TokenUsage } from "@amykit/core";

/** The shape `claude -p --output-format json` prints. */
export interface ClaudeEnvelope {
  result?: string;
  is_error?: boolean;
  api_error_status?: number | string | null;
  stop_reason?: string | null;
  total_cost_usd?: number;
  duration_ms?: number;
  usage?: {
    input_tokens?: number;
    output_tokens?: number;
    cache_read_input_tokens?: number;
    cache_creation_input_tokens?: number;
    /**
     * How the cache writes split by time to live.
     *
     * This is present in real envelopes and matters: a one-hour write is
     * billed at twice the input rate, so ignoring the split undercounts a
     * cache-heavy run badly. One real run had all 10,232 of its cache writes
     * at one hour, which is a 60% difference in the computed cost.
     */
    cache_creation?: {
      ephemeral_1h_input_tokens?: number;
      ephemeral_5m_input_tokens?: number;
    };
  };
  modelUsage?: Record<string, unknown>;
}

export interface ParsedRun {
  outcome: AgentOutcome;
  text: string;
  model: string;
  tokens?: TokenUsage;
  costUsd?: number;
  costSource: CostSource;
  durationMs?: number;
}

/**
 * Reads the envelope, or says it could not.
 *
 * Returns null rather than throwing, because a harness that printed something
 * unexpected is a run to classify, not an exception to unwind.
 */
export function parseEnvelope(stdout: string): ClaudeEnvelope | null {
  const trimmed = stdout.trim();
  if (!trimmed.startsWith("{")) return null;

  try {
    return JSON.parse(trimmed) as ClaudeEnvelope;
  } catch {
    return null;
  }
}

/**
 * Which of the four outcomes this run was.
 *
 * Read off the envelope, not off stderr. A rate limit and a failure want
 * opposite responses, and guessing between them from log text is how a relay
 * ends up escalating to an expensive model over a quota problem.
 *
 * Known limit: a rate limit severe enough that no envelope is printed
 * classifies as `failed`. That is honest rather than clever — when a real
 * throttled envelope is in hand, its shape goes here.
 */
export function classify(envelope: ClaudeEnvelope | null, exitOk: boolean): AgentOutcome {
  if (!envelope) return exitOk ? "completed" : "abandoned";

  if (isRateLimit(envelope.api_error_status)) return "rate-limited";
  if (envelope.is_error === true || !exitOk) return "failed";

  return "completed";
}

function isRateLimit(status: number | string | null | undefined): boolean {
  if (status === undefined || status === null) return false;
  if (typeof status === "number") return status === 429;
  return status.includes("429");
}

/** The token counts, if the envelope carried them. */
export function tokensOf(envelope: ClaudeEnvelope | null): TokenUsage | undefined {
  const usage = envelope?.usage;
  if (!usage) return undefined;

  const oneHour = usage.cache_creation?.ephemeral_1h_input_tokens;

  return {
    input: usage.input_tokens ?? 0,
    output: usage.output_tokens ?? 0,
    cacheRead: usage.cache_read_input_tokens ?? 0,
    cacheWrite: usage.cache_creation_input_tokens ?? 0,
    ...(oneHour === undefined ? {} : { cacheWrite1h: oneHour }),
  };
}

/**
 * The model the run actually used.
 *
 * `modelUsage` is keyed by it, decorations and all, which is more truthful
 * than what was asked for: a fallback would have changed it.
 */
export function modelOf(envelope: ClaudeEnvelope | null, asked: string): string {
  const keys = Object.keys(envelope?.modelUsage ?? {});
  return keys[0] ?? asked;
}

export function parseRun(stdout: string, exitOk: boolean, asked: string): ParsedRun {
  const envelope = parseEnvelope(stdout);
  const tokens = tokensOf(envelope);
  const reported = envelope?.total_cost_usd;

  return {
    outcome: classify(envelope, exitOk),
    // The envelope puts the answer in `result`; without one, the raw output
    // is all there is.
    text: envelope?.result ?? stdout,
    model: modelOf(envelope, asked),
    tokens,
    costUsd: typeof reported === "number" ? reported : undefined,
    // The harness knows the plan and the discounts, so what it says beats
    // anything worked out from a price table.
    // Only ever `reported` or `unknown` here. Working a cost out from a
    // price table is the caller's job, and claiming `computed` without
    // computing would be the exact confusion `costSource` exists to prevent.
    costSource: typeof reported === "number" ? "reported" : "unknown",
    durationMs: envelope?.duration_ms,
  };
}

export { ClaudeHarness, ISOLATED, lend } from "./ClaudeHarness.js";
export type { ClaudeHarnessConfig } from "./ClaudeHarness.js";
export { classify, modelOf, parseEnvelope, parseRun, tokensOf } from "./envelope.js";
export type { ClaudeEnvelope, ParsedRun } from "./envelope.js";
export { configSchema } from "./config.js";
export { plugin } from "./plugin.js";
export { ClaudeUsageReader, parseClaudeUsage } from "./usage.js";
export type { ClaudeUsageReaderOptions } from "./usage.js";

import { definePlugin } from "@amykit/core";
import { contributeTiers, contributeUsage } from "@amykit/agent-kit";
import { ClaudeHarness } from "./ClaudeHarness.js";
import { configSchema } from "./config.js";
import { ClaudeUsageReader } from "./usage.js";

export const plugin = definePlugin<typeof configSchema>({
  name: "@amykit/plugin-claude",
  configSchema,
  register(registry, ctx) {
    const tiers = ctx.config.models;

    // Contributed rather than mounted as the `agent` port: only one plugin
    // can own a port, and three harnesses that each wanted to be *the* agent
    // would refuse to mount together. The relay composes what is contributed.
    contributeTiers(registry, {
      harness: "claude",
      // The envelope carries `total_cost_usd`, and a cost the harness
      // reported beats anything a table could work out, so a missing row
      // never leaves a ceiling in money with nothing to spend against it.
      pricesItsOwnRuns: true,
      models: tiers.length > 0 ? tiers : [(ctx.config.model) || ""],
      make: (model) =>
        new ClaudeHarness(ctx.runner, {
          model: model || undefined,
          timeoutMs: ctx.config.timeoutMs,
        }),
    });
    contributeUsage(registry, new ClaudeUsageReader(ctx.runner, { timeoutMs: ctx.config.timeoutMs }));
  },
});

import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { CommandRunner } from "@amykit/core";
import type { UsageReader, UsageResult } from "@amykit/agent-kit";

interface ClaudeUsagePeriod {
  readonly utilization?: unknown;
  readonly resets_at?: unknown;
}

interface ClaudeUsageDocument {
  readonly five_hour?: ClaudeUsagePeriod;
  readonly seven_day?: ClaudeUsagePeriod;
}

export interface ClaudeUsageReaderOptions {
  readonly timeoutMs?: number;
  readonly token?: () => string | undefined;
}

/** Reads Claude's account windows without asking Claude to run an agent turn. */
export class ClaudeUsageReader implements UsageReader {
  readonly label = "Claude";

  constructor(
    private readonly runner: CommandRunner,
    private readonly options: ClaudeUsageReaderOptions = {},
  ) {}

  async read(): Promise<UsageResult> {
    const token = this.options.token?.() ?? oauthToken();
    if (!token) return { unavailable: "Claude usage is unavailable: no OAuth token is configured" };

    try {
      const result = await this.runner.run(
        "curl",
        ["--fail", "--silent", "--show-error", "--config", "-", "https://api.anthropic.com/api/oauth/usage"],
        {
          // A curl config on stdin keeps the bearer token out of argv and process listings.
          stdin: `header = "Authorization: Bearer ${token}"\n`,
          timeoutMs: this.options.timeoutMs,
        },
      );
      if (!result.ok) return { unavailable: "Claude usage is unavailable" };
      return parseClaudeUsage(result.stdout);
    } catch {
      return { unavailable: "Claude usage is unavailable" };
    }
  }
}

/** Normalizes the account endpoint's fractions into percentages. */
export function parseClaudeUsage(json: string): UsageResult {
  let document: ClaudeUsageDocument;
  try {
    document = JSON.parse(json) as ClaudeUsageDocument;
  } catch {
    return { unavailable: "Claude usage returned invalid JSON" };
  }
  const windows = [
    windowOf("five-hour", document.five_hour),
    windowOf("seven-day", document.seven_day),
  ].flatMap((window) => window ? [window] : []);
  return windows.length > 0 ? { windows } : { unavailable: "Claude usage returned no measured windows" };
}

function windowOf(label: string, period: ClaudeUsagePeriod | undefined) {
  if (!period || typeof period.utilization !== "number" || !Number.isFinite(period.utilization)) return undefined;
  const resetsAt = typeof period.resets_at === "string" && !Number.isNaN(Date.parse(period.resets_at))
    ? period.resets_at
    : undefined;
  return {
    label,
    usedPercent: Math.max(0, Math.min(100, period.utilization * 100)),
    ...(resetsAt ? { resetsAt } : {}),
  };
}

function oauthToken(): string | undefined {
  if (process.env.CLAUDE_CODE_OAUTH_TOKEN) return process.env.CLAUDE_CODE_OAUTH_TOKEN;
  try {
    const credentials = JSON.parse(fs.readFileSync(path.join(os.homedir(), ".claude", ".credentials.json"), "utf8")) as {
      claudeAiOauth?: { accessToken?: unknown };
    };
    return typeof credentials.claudeAiOauth?.accessToken === "string" ? credentials.claudeAiOauth.accessToken : undefined;
  } catch {
    return undefined;
  }
}
